import { defineConfig, loadEnv } from 'vite'
import react from '@vitejs/plugin-react'

const PRIVATE_PATHS = ['/login', '/logout', '/register', '/create', '/myposts/', '/profile/', '/posts/*/edit']

/**
 * Fills %SITE_URL% in index.html (canonical / Open Graph URLs must be absolute) and serves or emits robots.txt.
 * The sitemap itself is generated by the API from the database; the host rewrites /sitemap.xml to it (see vercel.json).
 */
function seo(siteUrl) {
  const robots = [
    'User-agent: *',
    ...PRIVATE_PATHS.map((p) => `Disallow: ${p}`),
    'Allow: /',
    '',
    `Sitemap: ${siteUrl}/sitemap.xml`,
    '',
  ].join('\n')
  return {
    name: 'safin-seo',
    transformIndexHtml: (html) => html.replaceAll('%SITE_URL%', siteUrl),
    configureServer(server) {
      server.middlewares.use('/robots.txt', (req, res) => {
        res.setHeader('Content-Type', 'text/plain; charset=utf-8')
        res.end(robots)
      })
    },
    generateBundle() {
      this.emitFile({ type: 'asset', fileName: 'robots.txt', source: robots })
    },
  }
}

// In development the client talks to the API through Vite's proxy, so it works on whatever
// port Vite ends up on (3000 may be taken) and without any CORS configuration.
export default defineConfig(({ mode, command }) => {
  const env = loadEnv(mode, process.cwd(), '')
  const target = env.VITE_PROXY_TARGET || 'http://localhost:5000'
  const siteUrl = (env.VITE_SITE_URL || 'http://localhost:3000').replace(/\/+$/, '')
  if (command === 'build' && !env.VITE_SITE_URL) {
    console.warn('\n⚠  VITE_SITE_URL is not set: canonical, Open Graph and robots.txt URLs will point to http://localhost:3000.\n')
  }
  return {
    plugins: [react(), seo(siteUrl)],
    server: {
      port: 3000,
      proxy: {
        '/api': { target, changeOrigin: true },
        '/uploads': { target, changeOrigin: true },
        '/sitemap.xml': { target, changeOrigin: true },
      },
    },
  }
})
